import http from 'node:http';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const STATIC_FILES = new Map(Object.entries({"/index.html":"","/app.js":"","/manifest.webmanifest":"","/style.css":"","/service-worker.js":"","/icons/icon.svg":"","/icons/icon-512.png":"","/icons/icon-192.png":""}).map(([name, data]) => [name, Buffer.from(data, 'base64')]));
const PORT = Number(process.env.PORT) || 3000;
const SOURCE_URL = process.env.FUEL_SOURCE_URL || 'https://bensinpriser.nu/karta/data';
const SOURCE_NAME = 'Bensinpriser.nu';
const FRESH_MS = 15 * 60 * 1000;
const MAX_STALE_MS = 2 * 60 * 60 * 1000;
const MAX_BYTES = 12 * 1024 * 1024;
const MAX_STATIONS = 12000;

const state = { stations: [], fetchedAt: null, lastError: null, lastAttemptAt: 0, pending: null };
const fuelFields = {
  '95': 'price95', '98': 'price98', diesel: 'priceDiesel',
  e85: 'priceEtanol', hvo100: 'priceBiodiesel', fordonsgas: 'priceFordonsgas',
};

export function normalizeStations(raw) {
  if (!Array.isArray(raw)) throw new Error('Datakällan svarade inte med en stationslista.');
  if (raw.length > MAX_STATIONS) throw new Error('Stationslistan var oväntat stor.');
  const ids = new Set();
  return raw.flatMap((item, index) => {
    if (!item || typeof item !== 'object' || Array.isArray(item)) return [];
    const lat = Number(item.lat);
    const lng = Number(item.lng);
    if (!Number.isFinite(lat) || !Number.isFinite(lng) || lat < 55.1 || lat > 69.2 || lng < 10.7 || lng > 24.4) return [];
    const id = String(item.id ?? `s-${index}`);
    if (ids.has(id)) return [];
    ids.add(id);
    const prices = {};
    for (const [fuel, field] of Object.entries(fuelFields)) {
      const value = item[field];
      // Null, zero and empty prices are NOT reported prices.
      if (value === null || value === undefined || value === '') continue;
      const price = Number(value);
      const upper = fuel === 'fordonsgas' ? 70 : 50;
      if (Number.isFinite(price) && price >= 5 && price <= upper) prices[fuel] = price;
    }
    const short = value => String(value ?? '').trim().slice(0, 130);
    const brand = short(item.company) || 'Fristående';
    const city = short(item.commune);
    const county = short(item.county);
    const address = short(item.address);
    let sourceUrl = 'https://bensinpriser.nu/karta';
    if (typeof item.link === 'string' && item.link.length < 500) {
      try {
        const candidate = new URL(item.link, 'https://bensinpriser.nu');
        if (candidate.protocol === 'https:' && ['bensinpriser.nu', 'www.bensinpriser.nu'].includes(candidate.hostname)) sourceUrl = candidate.href;
      } catch { /* invalid link: use source homepage */ }
    }
    return [{ id, brand, city, county, address, lat, lng, prices, sourceUrl }];
  });
}

async function readSource() {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 20000);
  try {
    const response = await fetch(SOURCE_URL, {
      headers: { 'Accept': 'application/json', 'User-Agent': 'Tankkollen/1.0 (personal fuel-price viewer)' },
      signal: controller.signal,
      redirect: 'follow',
    });
    if (!response.ok) throw new Error(`Datakällan svarade med HTTP ${response.status}.`);
    const declaredLength = Number(response.headers.get('content-length'));
    if (declaredLength > MAX_BYTES) throw new Error('Datakällans svar är för stort.');
    if (!response.body) throw new Error('Tomt svar från datakällan.');
    const chunks = [];
    let size = 0;
    for await (const chunk of response.body) {
      size += chunk.length;
      if (size > MAX_BYTES) throw new Error('Datakällans svar överskred storleksgränsen.');
      chunks.push(chunk);
    }
    const json = JSON.parse(Buffer.concat(chunks).toString('utf8'));
    const stations = normalizeStations(json);
    if (stations.length === 0) throw new Error('Inga stationer kunde läsas ur datakällan.');
    return stations;
  } finally { clearTimeout(timeout); }
}

async function getStations(force = false) {
  if (state.pending) await state.pending;
  const age = state.fetchedAt ? Date.now() - Date.parse(state.fetchedAt) : Infinity;
  if (!force && age < FRESH_MS) return state;
  // Även manuell uppdatering begränsas för att inte överbelasta priskällan.
  if (force && age < 60 * 1000) return state;
  // Efter fel: undvik att varje besökare gör ett nytt anrop till källan.
  if (state.lastError && Date.now() - state.lastAttemptAt < 3 * 60 * 1000) return state;
  if (Date.now() - state.lastAttemptAt < 60 * 1000) return state;
  state.lastAttemptAt = Date.now();
  state.pending = (async () => {
    try {
      const stations = await readSource();
      state.stations = stations;
      state.fetchedAt = new Date().toISOString();
      state.lastError = null;
      console.log(`[källa] ${stations.length} stationer hämtade ${state.fetchedAt}`);
    } catch (error) {
      state.lastError = error instanceof Error ? error.message : String(error);
      console.error(`[källa] ${state.lastError}`);
    }
  })();
  try { await state.pending; } finally { state.pending = null; }
  return state;
}

const mimeTypes = {
  '.html': 'text/html; charset=utf-8', '.js': 'application/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8', '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml', '.png': 'image/png', '.webp': 'image/webp',
  '.ico': 'image/x-icon', '.txt': 'text/plain; charset=utf-8', '.webmanifest': 'application/manifest+json; charset=utf-8',
};
function json(res, status, body) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store', 'X-Content-Type-Options': 'nosniff' });
  res.end(JSON.stringify(body));
}

export async function handler(req, res) {
  let url;
  try { url = new URL(req.url || '/', `http://${req.headers.host || 'localhost'}`); }
  catch { return json(res, 400, { error: 'Ogiltig URL' }); }
  if (req.method !== 'GET' && req.method !== 'HEAD') return json(res, 405, { error: 'Metoden stöds inte' });
  if (url.pathname === '/api/stations') {
    await getStations(url.searchParams.get('refresh') === '1');
    const age = state.fetchedAt ? Date.now() - Date.parse(state.fetchedAt) : Infinity;
    if (!state.fetchedAt || age > MAX_STALE_MS) {
      return json(res, 503, { error: 'Kunde inte hämta tillräckligt färska stationsuppgifter.', details: state.lastError, source: SOURCE_NAME });
    }
    return json(res, 200, {
      source: SOURCE_NAME, sourceUrl: 'https://bensinpriser.nu',
      fetchedAt: state.fetchedAt, stale: Boolean(state.lastError) || age >= FRESH_MS,
      caution: 'Användarrapporterade priser, kan vara upp till tre dygn gamla enligt källans datametodik. Kontrollera priset vid pumpen.',
      stations: state.stations,
    });
  }
  if (url.pathname === '/api/health') return json(res, 200, { ok: true, sourceFetchedAt: state.fetchedAt, stationCount: state.stations.length });
  let requested;
  try { requested = decodeURIComponent(url.pathname); } catch { return json(res, 400, { error: 'Ogiltig sökväg' }); }
  if (requested.includes('\0')) return json(res, 400, { error: 'Ogiltig sökväg' });
  const filename = requested === '/' ? '/index.html' : requested;
  const file = STATIC_FILES.get(filename);
  if (!file) return json(res, 404, { error: 'Sidan hittades inte' });
  const mime = mimeTypes[path.extname(filename)] || 'application/octet-stream';
  res.writeHead(200, {
    'Content-Type': mime, 'Content-Length': file.length,
    'X-Content-Type-Options': 'nosniff',
    'Cache-Control': ['/index.html', '/app.js', '/service-worker.js', '/manifest.webmanifest'].includes(filename) ? 'no-cache' : 'public, max-age=300',
  });
  if (req.method === 'HEAD') return res.end();
  return res.end(file);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const server = http.createServer((req, res) => { handler(req, res).catch(err => {
    console.error(err);
    if (!res.headersSent) json(res, 500, { error: 'Serverfel' }); else res.end();
  }); });
  server.listen(PORT, '0.0.0.0', () => console.log(`Tankkollen: http://localhost:${PORT}`));
}
